fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    // We use a classic lower‐bound style binary search:
    // after the loop, `left == right` is the first index where v[index] >= k.
    // Since we assume k is in v, v[left] == k.
    let mut left = 0;
    let mut right = v.len();
    while left < right {
        let mid = left + (right - left) / 2;
        if v[mid] < k {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    // At this point left == right, and because k is guaranteed to be in v,
    // v[left] must be == k.
    left
}

